import 'dart:io';
import 'dart:typed_data';
import 'dart:ui' as ui;
import 'package:flutter/foundation.dart';
import 'package:flutter/material.dart';
import 'package:flutter/rendering.dart';
import 'package:flutter_test/flutter_test.dart';
import 'package:venera/pages/reader/reader_hud.dart';
import 'helpers/hud_font_fixture.dart';

// Independent frozen 2.x presentation from cbdf3c56:scaffold.dart, rendered
// under the old Material 3 bodyMedium (14pt). Not a golden generated by the fix.
Widget legacyText(String value, ColorScheme scheme) => Stack(children: [
  Text(value, style: TextStyle(fontSize: 14, foreground: Paint()
    ..style = PaintingStyle.stroke ..strokeWidth = 1.4
    ..color = scheme.onInverseSurface)),
  Text(value),
]);

Widget legacyBattery(ColorScheme scheme) => Row(mainAxisSize: MainAxisSize.min,
  children: [
    Icon(Icons.battery_full_sharp, size: 16, color: scheme.onSurface, shadows: [
      for (var y = -1; y <= 1; y++)
        for (var x = -1; x <= 1; x++)
          if (x != 0 || y != 0)
            Shadow(color: scheme.onInverseSurface, offset: Offset(x * .8, y * .8)),
    ]),
    legacyText('100%', scheme),
  ]);

ThemeData hudTheme(Brightness brightness, {required bool legacy}) {
  final theme = ThemeData(useMaterial3: true, platform: TargetPlatform.iOS,
    colorScheme: ColorScheme.fromSeed(seedColor: Colors.blue, brightness: brightness),
    fontFamily: 'HudLatin', fontFamilyFallback: const ['HudCJK']);
  return legacy ? theme : theme.copyWith(textTheme: theme.textTheme.copyWith(
    bodyMedium: theme.textTheme.bodyMedium!.copyWith(fontSize: 16, height: 1.35)));
}

void main() {
  TestWidgetsFlutterBinding.ensureInitialized();
  setUpAll(loadHudTestFonts);
  final key = GlobalKey();

  Future<Uint8List> pixels(WidgetTester tester, String name) async {
    final bytes = await tester.runAsync(() async {
      final boundary = key.currentContext!.findRenderObject() as RenderRepaintBoundary;
      final image = await boundary.toImage(pixelRatio: 3);
      try {
        if (Platform.environment['HUD_EVIDENCE'] == '1') {
          final png = await image.toByteData(format: ui.ImageByteFormat.png);
          final path = File('build/reader-hud-evidence/$name.png');
          path.parent.createSync(recursive: true);
          path.writeAsBytesSync(png!.buffer.asUint8List());
        }
        final data = await image.toByteData(format: ui.ImageByteFormat.rawRgba);
        return Uint8List.fromList(data!.buffer.asUint8List());
      } finally { image.dispose(); }
    });
    return bytes!;
  }

  Future<void> pump(WidgetTester tester, Brightness brightness, int mode,
    Color background, double scale) async {
    // mode 0 = frozen 2.x, 1 = production repair, 2 = broken build276.
    final theme = hudTheme(brightness, legacy: mode == 0);
    final scheme = theme.colorScheme;
    Widget text(String value) => mode == 1 ? ReaderHudText(value) : legacyText(value, scheme);
    await tester.pumpWidget(MaterialApp(theme: theme,
      builder: (context, child) => MediaQuery(
        data: MediaQuery.of(context).copyWith(textScaler: TextScaler.linear(scale)),
        child: child!),
      home: Scaffold(body: Center(child: RepaintBoundary(key: key,
        child: SizedBox(width: 430, height: 105, child: ColoredBox(color: background,
          child: Stack(children: [
            Positioned(left: 25, right: 25, bottom: 13,
              child: Row(children: [
                Expanded(child: text('174 差距 : 75/80')),
                const SizedBox(width: 10),
                mode == 2
                  ? Text('08:38', style: TextStyle(fontSize: 14, color: scheme.onInverseSurface))
                  : text('08:38'),
                const SizedBox(width: 10),
                mode == 1
                  ? const ReaderHudBattery(icon: Icons.battery_full_sharp, level: 100)
                  : mode == 2
                    ? Row(mainAxisSize: MainAxisSize.min, children: [
                        Icon(Icons.battery_full_sharp, size: 16, color: scheme.onSurface),
                        Text('100%', style: TextStyle(fontSize: 14, color: scheme.onInverseSurface)),
                      ])
                    : legacyBattery(scheme),
              ])),
          ])),
        ),
      )))));
    await tester.pumpAndSettle();
  }

  for (final brightness in Brightness.values) {
    for (final background in [Colors.white, Colors.black, const Color(0xFFB25159)]) {
      testWidgets('pixel parity with 2.x ${brightness.name} bg ${background.toARGB32()}', (tester) async {
        final suffix = '${brightness.name}-${background.toARGB32()}';
        await pump(tester, brightness, 0, background, 1);
        final reference = await pixels(tester, 'legacy-$suffix');
        await pump(tester, brightness, 1, background, 1);
        final fixed = await pixels(tester, 'fixed-$suffix');
        await pump(tester, brightness, 2, background, 1);
        final broken = await pixels(tester, 'broken276-$suffix');
        var different = 0;
        for (var i = 0; i < reference.length; i += 4) {
          if (reference[i] != fixed[i] || reference[i + 1] != fixed[i + 1] ||
              reference[i + 2] != fixed[i + 2] || reference[i + 3] != fixed[i + 3]) different++;
        }
        debugPrint('HUD_PIXEL_PARITY $suffix differingPixels=$different totalPixels=${reference.length ~/ 4}');
        expect(different, 0, reason: 'Actual raster must match the independent 2.x reference');
        expect(listEquals(broken, reference), isFalse,
          reason: 'The same acceptance check must reject build276');
        expect(tester.takeException(), isNull);
      });
    }
  }

  for (final scale in [1.0, 1.5, 2.0]) {
    for (final width in [80.0, 240.0, 600.0]) {
      testWidgets('stroke/fill geometry locked scale=$scale width=$width', (tester) async {
        await tester.pumpWidget(MaterialApp(theme: hudTheme(Brightness.dark, legacy: false),
          home: Scaffold(body: MediaQuery(
            data: MediaQueryData(textScaler: TextScaler.linear(scale)),
            child: DefaultTextStyle(
              style: const TextStyle(fontSize: 30, fontWeight: FontWeight.w900,
                letterSpacing: 5, height: 2),
              child: Center(child: SizedBox(width: width,
                child: const ReaderHudText('174 差距 : 75/80'))),
            ),
          ))));
        await tester.pump();
        RenderParagraph paragraph(String name) => tester.renderObject<RenderParagraph>(
          find.descendant(of: find.byKey(ValueKey(name)), matching: find.byType(RichText)));
        final stroke = paragraph('reader-hud-stroke');
        final fill = paragraph('reader-hud-fill');
        expect(stroke.size, fill.size);
        expect(stroke.localToGlobal(Offset.zero), fill.localToGlobal(Offset.zero));
        expect(stroke.getDistanceToBaseline(TextBaseline.alphabetic),
          fill.getDistanceToBaseline(TextBaseline.alphabetic));
        const selection = TextSelection(baseOffset: 0, extentOffset: 16);
        final a = stroke.getBoxesForSelection(selection);
        final b = fill.getBoxesForSelection(selection);
        expect(a.map((box) => box.toRect()), b.map((box) => box.toRect()));
        final s = stroke.text.style!;
        final f = fill.text.style!;
        expect(s.fontSize, 14);
        expect(f.fontSize, 14);
        expect(s.height, 1.43);
        expect(s.fontWeight, FontWeight.w400);
        expect(s.letterSpacing, .25);
        expect(s.foreground!.style, PaintingStyle.stroke);
        expect(f.foreground!.style, PaintingStyle.fill);
        expect(s.foreground!.color, isNot(f.foreground!.color));
        expect(s.foreground!.strokeWidth, 1.4);
        expect(tester.takeException(), isNull);
      });
    }
  }

  testWidgets('page updates replace both glyph layers and semantics only once', (tester) async {
    final semantics = tester.ensureSemantics();
    addTearDown(semantics.dispose);
    late StateSetter change;
    var value = '174 差距 : 75/80';
    await tester.pumpWidget(MaterialApp(home: Scaffold(body: StatefulBuilder(
      builder: (_, setState) {
        change = setState;
        return ReaderHudText(value);
      },
    ))));
    await tester.pump();
    expect(find.bySemanticsLabel(value), findsOneWidget);
    change(() => value = '175 新章 : 1/60');
    await tester.pump();
    expect(find.text('174 差距 : 75/80'), findsNothing);
    expect(find.text(value), findsNWidgets(2));
    expect(find.bySemanticsLabel(value), findsOneWidget);
    expect(tester.takeException(), isNull);
  });

  testWidgets('battery has legacy eight-direction crisp outline', (tester) async {
    await tester.pumpWidget(MaterialApp(home: Scaffold(body:
      const ReaderHudBattery(icon: Icons.battery_1_bar_sharp, level: 35))));
    final icon = tester.widget<Icon>(find.byType(Icon));
    expect(icon.size, 16);
    expect(icon.shadows, hasLength(8));
    expect(icon.shadows!.every((shadow) => shadow.blurRadius == 0), isTrue);
    expect(icon.shadows!.map((s) => s.offset).toSet(), {
      const Offset(-.8, -.8), const Offset(0, -.8), const Offset(.8, -.8),
      const Offset(-.8, 0), const Offset(.8, 0),
      const Offset(-.8, .8), const Offset(0, .8), const Offset(.8, .8),
    });
    expect(tester.widget<ReaderHudText>(find.byType(ReaderHudText)).text, '35%');
  });
}
